// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ListGatewayConfigs List the shop's gateway settings
	// (GET /admin/gateway-config)
	ListGatewayConfigs(ctx context.Context, request ListGatewayConfigsRequestObject) (ListGatewayConfigsResponseObject, error)
	// PutGatewayConfig Set the shop's credentials for a gateway
	// (PUT /admin/gateway-config/{gateway})
	PutGatewayConfig(ctx context.Context, request PutGatewayConfigRequestObject) (PutGatewayConfigResponseObject, error)
	// TestGatewayConfig Check the stored credentials against the gateway
	// (POST /admin/gateway-config/{gateway}/test)
	TestGatewayConfig(ctx context.Context, request TestGatewayConfigRequestObject) (TestGatewayConfigResponseObject, error)
	// ListTransactions List the shop's transactions, newest first
	// (GET /admin/transactions)
	ListTransactions(ctx context.Context, request ListTransactionsRequestObject) (ListTransactionsResponseObject, error)
	// GetTransaction Get a transaction and its refunds
	// (GET /admin/transactions/{id})
	GetTransaction(ctx context.Context, request GetTransactionRequestObject) (GetTransactionResponseObject, error)
	// AuthorizePayment Authorize a payment (Variant A)
	// (POST /internal/authorize)
	AuthorizePayment(ctx context.Context, request AuthorizePaymentRequestObject) (AuthorizePaymentResponseObject, error)
	// CapturePayment Capture an authorized payment
	// (POST /internal/capture)
	CapturePayment(ctx context.Context, request CapturePaymentRequestObject) (CapturePaymentResponseObject, error)
	// GetGatewayCapabilities What a gateway supports, and whether the shop has it set up
	// (GET /internal/gateway-capabilities/{gateway})
	GetGatewayCapabilities(ctx context.Context, request GetGatewayCapabilitiesRequestObject) (GetGatewayCapabilitiesResponseObject, error)
	// RefundPayment Refund a captured payment
	// (POST /internal/refund)
	RefundPayment(ctx context.Context, request RefundPaymentRequestObject) (RefundPaymentResponseObject, error)
	// GetInternalTransaction Get a transaction and its refunds
	// (GET /internal/transactions/{id})
	GetInternalTransaction(ctx context.Context, request GetInternalTransactionRequestObject) (GetInternalTransactionResponseObject, error)
	// VoidPayment Void an authorization
	// (POST /internal/void)
	VoidPayment(ctx context.Context, request VoidPaymentRequestObject) (VoidPaymentResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

